where slug = 'oeongchi-beach' and description = '대포항과 속초해수욕장 사이에 있는 백사장 약 400m의 작은 해변으로, 큰 해변보다 한적해요. 여름 개장 기간에는 샤워장·탈의실과 안전요원이 운영되고, 해안까지 경사로와 데크길이 있어 휠체어로도 다가갈 수 있어요.';
update public.places set description = '토왕골의 계단식 암반을 따라 작은 폭포와 소 여섯 개가 층층이 이어진 곳으로, 위쪽으로 비룡폭포와 토왕성폭포가 차례로 나옵니다. 소공원에서 비룡폭포로 가는 탐방로 중간에 있어 따로 찾아가기보다 지나는 길에 보는 곳입니다.'
where slug = 'yukdam-falls' and description = '토왕골의 계단식 암반을 따라 작은 폭포와 소 여섯 개가 층층이 이어진 곳으로, 위쪽으로 비룡폭포와 토왕성폭포가 차례로 나와요. 소공원에서 비룡폭포로 가는 탐방로 중간에 있어 따로 찾아가기보다 지나는 길에 보는 곳이에요.';
update public.places set description = '청초호 서쪽 언덕에서 1992년 발굴된 신석기 말~청동기 초의 유적으로, 움집터 7기와 고인돌 2기가 확인되어 국가 사적으로 지정되었습니다. 고인돌에서는 남한에서 처음으로 부채꼴 청동도끼가 나왔습니다. 건물 없이 야외에 유적만 있어 언제든 볼 수 있고, 20~30분이면 둘러볼 수 있습니다.'
where slug = 'joyang-dong-prehistoric-site' and description = '청초호 서쪽 언덕에서 1992년 발굴된 신석기 말~청동기 초의 유적으로, 움집터 7기와 고인돌 2기가 확인되어 국가 사적으로 지정되었어요. 고인돌에서는 남한에서 처음으로 부채꼴 청동도끼가 나왔어요. 건물 없이 야외에 유적만 있어 언제든 볼 수 있고, 20~30분이면 둘러볼 수 있어요.';
update public.places set description = '조양동에 있는 해발 230m 남짓의 낮은 산으로, 속초 8경 중 하나입니다. 어느 들머리에서 올라도 정상까지 30~40분이면 닿고, 길목에 운동시설과 쉼터, 전망대가 있습니다. 정상에서는 속초 시가지와 동해, 울산바위와 달마봉 같은 설악산 능선이 보여 가벼운 산행이나 해돋이 산책으로 찾기 좋습니다.'
where slug = 'cheongdaesan' and description = '조양동에 있는 해발 230m 남짓의 낮은 산으로, 속초 8경 중 하나예요. 어느 들머리에서 올라도 정상까지 30~40분이면 닿고, 길목에 운동시설과 쉼터, 전망대가 있어요. 정상에서는 속초 시가지와 동해, 울산바위와 달마봉 같은 설악산 능선이 보여 가벼운 산행이나 해돋이 산책으로 찾기 좋아요.';
update public.places set description = '속초 시내 한가운데 청초호 호숫가에 꾸민 공원으로, 산책로와 벤치, 밤에 불을 밝히는 조형물이 있고 호수 위 정자 청초정에서 설악산과 바다 쪽을 볼 수 있습니다. 공원 옆 73.4m 높이의 엑스포타워 전망대에 오르면 동해와 설악산, 시내가 한눈에 보입니다. 평탄한 길이라 아이와 함께 1시간 안팎으로 걷기 좋고, 야경을 보러 저녁에 찾아도 좋습니다.'
where slug = 'cheongcho-lake-park' and description = '속초 시내 한가운데 청초호 호숫가에 꾸민 공원으로, 산책로와 벤치, 밤에 불을 밝히는 조형물이 있고 호수 위 정자 청초정에서 설악산과 바다 쪽을 볼 수 있어요. 공원 옆 73.4m 높이의 엑스포타워 전망대에 오르면 동해와 설악산, 시내가 한눈에 보여요. 평탄한 길이라 아이와 함께 1시간 안팎으로 걷기 좋고, 야경을 보러 저녁에 찾아도 좋아요.';
update public.places set cautions = '엑스포타워 전망대는 09:00~22:00 운영하고 21:30에 입장을 마감합니다.'
where slug = 'cheongcho-lake-park' and cautions = '엑스포타워 전망대는 09:00~22:00 운영하고 21:30에 입장을 마감해요.';
update public.places set description = '아바이마을 끝자락의 작은 해변으로, 방파제가 바다를 감싸 파도가 잔잔하고 물이 얕아 어린아이와 물놀이하기 좋습니다. 등대가 선 방파제 옆이라 다른 해변보다 한적하고, 아바이마을 구경이나 순대 식사와 묶어 들르기에 맞습니다.'
where slug = 'cheongho-beach' and description = '아바이마을 끝자락의 작은 해변으로, 방파제가 바다를 감싸 파도가 잔잔하고 물이 얕아 어린아이와 물놀이하기 좋아요. 등대가 선 방파제 옆이라 다른 해변보다 한적하고, 아바이마을 구경이나 순대 식사와 묶어 들르기에 맞아요.';
update public.places set description = '상·중·하 3단을 합쳐 약 320m에 이르는 토왕성폭포를 멀리서 바라보는 전망대로, 비룡폭포 탐방로를 약 400m 늘려 만들었습니다. 소공원에서 육담폭포·비룡폭포를 지나 약 2.8km, 편도 1시간 30분 안팎이 걸리며, 비룡폭포부터 전망대까지는 계단이 많아 가장 힘든 구간입니다. 겨울에는 폭포가 얼어 큰 빙폭이 되고, 날씨가 흐리면 폭포가 잘 보이지 않을 수 있습니다.'
where slug = 'towangseong-falls-observatory' and description = '상·중·하 3단을 합쳐 약 320m에 이르는 토왕성폭포를 멀리서 바라보는 전망대로, 비룡폭포 탐방로를 약 400m 늘려 만들었어요. 소공원에서 육담폭포·비룡폭포를 지나 약 2.8km, 편도 1시간 30분 안팎이 걸리며, 비룡폭포부터 전망대까지는 계단이 많아 가장 힘든 구간이에요. 겨울에는 폭포가 얼어 큰 빙폭이 되고, 날씨가 흐리면 폭포가 잘 보이지 않을 수 있어요.';
